/**
 * Minimal argparse-compatible command-line parsing for test13.
 *
 * Supports the subset of Python's argparse used by the original script:
 *   - required string options: --key, --data
 *   - both "--opt value" and "--opt=value" forms
 *   - -h / --help (prints help to stdout, exits 0)
 *   - usage/error output and exit codes matching argparse (errors -> exit 2)
 */

const OPTIONS = [
  { name: 'key', metavar: 'KEY', help: null },
  { name: 'data', metavar: 'DATA', help: null },
];

const DESTS = OPTIONS.map((o) => o.name);

function usageLine(prog) {
  return `usage: ${prog} [-h] --key KEY --data DATA`;
}

function helpText(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help   show this help message and exit',
    '  --key KEY',
    '  --data DATA',
  ];
  return lines.join('\n');
}

function fail(prog, message) {
  process.stderr.write(`${usageLine(prog)}\n${prog}: error: ${message}\n`);
  process.exit(2);
}

/**
 * Parse argv (arguments after `node script`, i.e. process.argv.slice(2)).
 *
 * @param {string[]} argv
 * @param {string} prog program name used in usage/error output
 * @returns {{key: string, data: string}}
 */
export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '-h' || arg === '--help') {
      process.stdout.write(`${helpText(prog)}\n`);
      process.exit(0);
    }

    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      const flag = eq === -1 ? arg : arg.slice(0, eq);
      const dest = DESTS.includes(flag.slice(2)) ? flag.slice(2) : null;

      if (dest === null) {
        extras.push(arg);
        continue;
      }

      if (eq !== -1) {
        values[dest] = arg.slice(eq + 1);
      } else {
        const next = argv[i + 1];
        if (next === undefined || (next.startsWith('-') && next !== '-')) {
          fail(prog, `argument --${dest}: expected one argument`);
        }
        values[dest] = next;
        i++;
      }
    } else {
      extras.push(arg);
    }
  }

  const missing = DESTS.filter((d) => values[d] === undefined);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.map((d) => `--${d}`).join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { key: values.key, data: values.data };
}

/**
 * Port of test13.py: round-trip AES ECB encrypt/decrypt, printing results
 * as Python bytes reprs (matching the original script's print(ciphertext) /
 * print(plaintext) output).
 */

import { AESModeOfOperationECB } from './lib/aes-ecb.mjs';
import { encodeUtf8, bytesToPythonRepr } from './lib/pybytes.mjs';
import { parseArgs } from './lib/cli-args.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2), 'test13.mjs');

  // Test round-trip encryption/decryption with ECB
  const aes = new AESModeOfOperationECB(encodeUtf8(args.key)); // Initialize AES ECB cipher
  const ciphertext = aes.encrypt(encodeUtf8(args.data)); // Encrypt plaintext
  const plaintext = aes.decrypt(ciphertext); // Decrypt ciphertext back
  console.log(bytesToPythonRepr(ciphertext));
  console.log(bytesToPythonRepr(plaintext));
}

main();

import { parseArgs } from './lib/cli-args.mjs';

const prog = 'test13.mjs';

// --opt value form
let r = parseArgs(['--key', 'yPcJ.h9oOX7e5!cV', '--data', '=b=M1F[g)],C0CZ6'], prog);
if (r.key !== 'yPcJ.h9oOX7e5!cV' || r.data !== '=b=M1F[g)],C0CZ6') throw new Error('space form failed: ' + JSON.stringify(r));

// --opt=value form
r = parseArgs(['--key=yPcJ.h9oOX7e5!cV', '--data==b=M1F[g)],C0CZ6'], prog);
if (r.key !== 'yPcJ.h9oOX7e5!cV' || r.data !== '=b=M1F[g)],C0CZ6') throw new Error('equals form failed: ' + JSON.stringify(r));

// mixed, reversed order
r = parseArgs(['--data', 'abc', '--key=def'], prog);
if (r.key !== 'def' || r.data !== 'abc') throw new Error('mixed form failed');

console.log('CLI-ARGS SELF-TESTS PASSED');

