mkdir -p /tmp/t13check/lib && cp /output/test13.mjs /tmp/t13check/ && cat > /tmp/t13check/lib/aes-ecb.mjs <<'EOF'
export class AESModeOfOperationECB {
  constructor(key) { if (![16,24,32].includes(key.length)) throw new RangeError('key'); }
  encrypt(d) { return d.slice(); }
  decrypt(d) { return d.slice(); }
}
EOF
cat > /tmp/t13check/lib/pybytes.mjs <<'EOF'
export function encodeUtf8(s) { return new TextEncoder().encode(s); }
export function bytesToPythonRepr(u8) { return "b'" + [...u8].map(b => (b>=32&&b<127&&b!==39&&b!==92)?String.fromCharCode(b):'\\x'+b.toString(16).padStart(2,'0')).join('') + "'"; }
EOF
cp /output/lib/cli-args.mjs /tmp/t13check/lib/ && cd /tmp/t13check && node test13.mjs --key 'yPcJ.h9oOX7e5!cV' --data '=b=M1F[g)],C0CZ6'; echo "rc=$?"; node test13.mjs; echo "rc=$?"; node test13.mjs -h; echo "rc=$?"; rm -rf /tmp/t13check
